def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Compute recent opponent behavior and overall stats
    opp_c = 0
    for _, o in history:
        if o == 'C':
            opp_c += 1

    defect_rate = (n - opp_c) / float(n)

    last_opp = history[-1][1]
    my_last = history[-1][0]

    # Check recent window (last 10 rounds) for defections
    recent_window = min(10, n)
    recent_start = n - recent_window
    recent_defects = 0
    for i in range(recent_start, n):
        if history[i][1] == 'D':
            recent_defects += 1

    # If the opponent has been very cooperative recently and historically, cooperate
    if recent_defects <= 2 and defect_rate < 0.3:
        # Occasionally probe if we are far from end game? 
        # Generally, stick to C if things look good.
        if n > 85 and defect_rate < 0.1:
             # Near end, exploit pure cooperators more often
             if rng.random() < 0.3:
                 return 'D'
        return 'C'

    # Strong retaliation against high defection rates or bursts
    if recent_defects >= 6 or defect_rate > 0.5:
        return 'D'

    # Standard Tit-for-Tat with Forgiveness logic
    if last_opp == 'D':
        # If we just defected too, and they defected, continue punishment unless they stop
        if my_last == 'D':
            # If we have been in a mutual D loop for > 2 rounds, try to break it if overall coop is okay
            # But generally, stay D if they are D
            if recent_defects > 4:
                return 'D'
            return 'D'
        else:
            # We cooperated, they defected. Retaliate immediately.
            return 'D'
    else:
        # Opponent cooperated.
        # Should we cooperate back? Yes, unless we are in a "punishment" phase that hasn't expired.
        # If we were punishing them (my_last == 'D') and they just played C, we should forgive and return to C.
        if my_last == 'D':
            # They stopped defecting. Return to cooperation.
            return 'C'
        else:
            # Both cooperating. Stay C.
            return 'C'
